<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tests | Lab Admin</title><style>body{margin:0;background:#f1f7fb;color:#12304c;font-family:Arial}.wrap{max-width:1120px;margin:42px auto;padding:0 20px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.back{color:#2476c7;text-decoration:none;font-weight:bold}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.card{background:#fff;border:1px solid #dce9f0;border-radius:14px;padding:24px;box-shadow:0 8px 22px #dce8ef}.field{margin:15px 0}.field label{display:block;margin-bottom:6px;font-size:13px;font-weight:bold}input,textarea,select{width:100%;padding:11px;box-sizing:border-box;border:1px solid #cbdce7;border-radius:8px;font:inherit}textarea{min-height:100px}button{border:0;border-radius:8px;padding:12px 18px;background:#16b9a7;color:white;font-weight:bold;cursor:pointer}.ok{margin-bottom:18px;padding:12px;border-radius:8px;background:#def9f2;color:#087a6b}.item{padding:15px 0;border-bottom:1px solid #e1ecf2}.item:last-child{border:0}.item h3{margin:0 0 5px}.item p{margin:0;color:#668099;line-height:1.5}.tag{display:inline-block;margin-top:7px;padding:4px 8px;border-radius:12px;background:#e5f8f3;color:#068b78;font-size:11px;font-weight:bold}@media(max-width:700px){.grid{grid-template-columns:1fr}.top{flex-direction:column;align-items:flex-start}}</style></head><body><main class="wrap"><header class="top"><div><h1>Tests</h1><p>Create a test and assign it to the service where it should appear.</p></div><a class="back" href="{{route('admin.dashboard')}}">← Dashboard</a></header>@if(session('success'))<div class="ok">{{session('success')}}</div>@endif<div class="grid"><section class="card"><h2>Add Test</h2><form method="post" action="{{route('admin.tests.store')}}" enctype="multipart/form-data">@csrf<div class="field"><label>Assign to service</label><select name="service_id" required><option value="">Select service</option>@foreach($services as $service)<option value="{{$service->id}}">{{$service->name}}</option>@endforeach</select></div><div class="field"><label>Test name</label><input name="name" required placeholder="e.g. Comprehensive Metabolic Panel"></div><div class="field"><label>Card heading</label><input name="heading" placeholder="Heading shown on the card"></div><div class="field"><label>Description</label><textarea name="description" placeholder="Test description shown on the service page"></textarea></div><div class="field"><label>Test photo</label><input type="file" name="image" accept="image/png,image/jpeg,image/webp"></div><button>Add test</button></form></section><section class="card"><h2>Assigned Tests</h2>@forelse($tests as $test)<article class="item"><h3>{{ $test->heading ?: $test->name }}</h3><p>{{ $test->description ?: 'No description added.' }}</p><span class="tag">{{ $test->service_name }}</span></article>@empty<p>No tests added yet.</p>@endforelse</section></div></main></body></html>
